data_contract.typescript:
export type HelpGuideKey = string; // chiave navigation con route, oppure 'general'

export type HelpBlock =
  | { type: 'paragraph'; text: string }
  | { type: 'steps'; items: string[] }             // elenco numerato
  | { type: 'list'; items: string[] }              // elenco puntato
  | { type: 'table'; headers: string[]; rows: string[][] }
  | { type: 'tip'; text: string }                  // "Suggerimento"
  | { type: 'warning'; text: string }              // "Attenzione"
  | { type: 'note'; text: string };                // avviso neutro (es. modulo in sviluppo)

export interface HelpSection {
  id: string;        // kebab-case inglese, stabile, identico tra IT ed EN
  title: string;
  blocks: HelpBlock[];
}

export interface HelpGuide {
  key: HelpGuideKey;
  title: string;
  summary: string;   // frase d'apertura
  sections: HelpSection[];
}
// Testo: solo testo semplice; unico markup inline ammesso **grassetto** (renderizzato <strong>).
// Contenuto: frontend/src/features/help/content/{it,en}/<key>.ts, export default HelpGuide.
